#include "contract_test.h"
#include "attention_and_fp_engine.h"
int main(){using namespace laya;SoftmaxTask t;t.ctx=test::ctx(Op::SOFTMAX_CAND,6,255,RowSpace::BATCH);t.src=test::ref(Buffer::HEAD_WORK);t.dst=test::ref(Buffer::HEAD_WORK);t.length=16;t.mode=1;t.src_region=3;t.dst_region=6;uint32_t out=0;test::require(attention_and_fp_engine::validate(t,2,128,out)&&out==16,"candidate softmax");t.length=15;test::require(!attention_and_fp_engine::validate(t,2,128,out),"must process all 16");t.length=16;t.ctx=test::ctx(Op::SOFTMAX_CAND,6,255,RowSpace::TOKEN,0,16);test::require(!attention_and_fp_engine::validate(t,2,128,out),"candidate task must be BATCH");
  QKTask q;q.ctx=test::ctx(Op::QK,2,1);q.qkv_ref={test::ref(Buffer::QKV,0),test::ref(Buffer::QKV,1)};q.kv=test::ref(Buffer::KV);q.score=test::ref(Buffer::SCORE_PROB);q.S=128;q.mask_mode=1;test::require(attention_and_fp_engine::validate(q,2,128,out)&&out==128,"QK slide key count");q.mask_mode=0;test::require(!attention_and_fp_engine::validate(q,2,128,out),"encoder1 must slide");q.mask_mode=1;q.S=127;test::require(!attention_and_fp_engine::validate(q,2,128,out),"QK S mismatch");}
